import os
import requests

def extract_invoice_fields(payload, config=None):
    config = config or {}
    api_key = os.getenv('DOCUSIGN_API_KEY')
    url = "https://api.docusign.net/esign/v2/accounts/{account_id}/envelopes"

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }

    data = {
        "emailSubject": "Please sign this document",
        "templateId": config.get('template_id', 'default_template'),
        "templateRoles": [
            {
                "email": config.get('signer_email', 'signer@example.com'),
                "name": config.get('signer_name', 'Signer'),
                "roleName": "signer"
            }
        ],
        "status": "sent"
    }

    response = requests.post(url, headers=headers, json=data)
    result = response.json()
    return result
